    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程唯一标识符",
              "sampleValue": "cal-demo-001"
            },
            "title": {
              "type": "string",
              "description": "今日日程标题",
              "sampleValue": "过敏药补货"
            },
            "dtStart": {
              "type": "string",
              "description": "今日日程开始时间",
              "sampleValue": "18:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "今日日程结束时间",
              "sampleValue": "19:00"
            }
          }
        ]
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "数据加载状态",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/air_fill.svg",
      "description": "空气循环实心图标，适合智能家居空气质量与空气管理场景的候选素材。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合今日日程摘要或日历事件入口的候选素材。"
    }
  ]
}

